VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := Motor_Running AND (Motor_Current > 124.5), PT := T#3S);

IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
    Motor_Stop := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
    Motor_Stop := FALSE;
END_IF;

